async def act(page):
    """
    From the current Dashboard, navigate to the Coupons report, set the date
    range 05/01/2021 -> 05/15/2023 using accessible controls (role-based),
    run the report action, and attempt to export a CSV. Best-effort only; the
    function avoids non-role selectors except for a narrow JS fallback that
    targets inputs named 'from' and 'to' if accessible textboxes are not
    present.
    """

    # Navigate to a likely coupons report path (relative navigation)
    await page.goto('/index.php/admin/report_salesrule/coupons/')
    await page.wait_for_timeout(800)

    from_value = '05/01/2021'
    to_value = '05/15/2023'

    # Prefer accessible textboxes named 'From'/'To'
    filled_any = False
    try:
        try:
            from_count = await page.get_by_role('textbox', name='From').count()
        except Exception:
            from_count = 0
        try:
            to_count = await page.get_by_role('textbox', name='To').count()
        except Exception:
            to_count = 0

        if from_count > 0:
            await page.get_by_role('textbox', name='From').first.fill(from_value)
            filled_any = True
        if to_count > 0:
            await page.get_by_role('textbox', name='To').first.fill(to_value)
            filled_any = True
    except Exception:
        # Narrowly ignore fill errors and try JS fallback
        filled_any = filled_any

    # Narrow JS fallback: only target inputs with name attributes 'from'/'to'
    if not filled_any:
        try:
            await page.evaluate(
                """
                (fromVal, toVal) => {
                    const f = document.querySelector('input[name="from"]');
                    const t = document.querySelector('input[name="to"]');
                    if (f) {
                        f.value = fromVal;
                        f.dispatchEvent(new Event('input', { bubbles: true }));
                        f.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                    if (t) {
                        t.value = toVal;
                        t.dispatchEvent(new Event('input', { bubbles: true }));
                        t.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                }
                """,
                from_value,
                to_value,
            )
            filled_any = True
        except Exception:
            filled_any = filled_any

    # If unable to set dates via accessible controls or the narrow fallback, stop.
    if not filled_any:
        return

    # Let the UI react to the inputs
    await page.wait_for_timeout(700)

    # Trigger the report using accessible button names if present
    try:
        if await page.get_by_role('button', name='Show Report').count() > 0:
            await page.get_by_role('button', name='Show Report').first.click()
            await page.wait_for_timeout(1200)
        elif await page.get_by_role('button', name='Refresh').count() > 0:
            await page.get_by_role('button', name='Refresh').first.click()
            await page.wait_for_timeout(1200)
        elif await page.get_by_role('button', name='Filter').count() > 0:
            await page.get_by_role('button', name='Filter').first.click()
            await page.wait_for_timeout(1200)
        elif await page.get_by_role('button', name='Apply').count() > 0:
            await page.get_by_role('button', name='Apply').first.click()
            await page.wait_for_timeout(1200)
        else:
            await page.wait_for_timeout(1200)
    except Exception:
        # Narrowly ignore interaction errors
        await page.wait_for_timeout(800)

    # Best-effort export to CSV using role-based selectors only
    filename = 'coupons_2021-05-01_to_2023-05-15.csv'
    try:
        # Try a direct Export button first
        if await page.get_by_role('button', name='Export').count() > 0:
            export_btn = page.get_by_role('button', name='Export').first
            try:
                async with page.expect_download() as dl:
                    await export_btn.click()
                download = await dl.value
                await download.save_as(filename)
                return
            except Exception:
                try:
                    await export_btn.click()
                except Exception:
                    pass

        # Try link-based export variants
        for link_name in ['Export', 'Export CSV', 'CSV', 'Download', 'Export as CSV']:
            if await page.get_by_role('link', name=link_name).count() > 0:
                export_link = page.get_by_role('link', name=link_name).first
                try:
                    async with page.expect_download() as dl:
                        await export_link.click()
                    download = await dl.value
                    await download.save_as(filename)
                    return
                except Exception:
                    try:
                        await export_link.click()
                    except Exception:
                        pass

        # Try combobox pattern: select CSV option then click Export button
        cbs = page.get_by_role('combobox')
        try:
            cb_count = await cbs.count()
        except Exception:
            cb_count = 0

        for i in range(cb_count):
            try:
                option_texts = await cbs.nth(i).all_inner_texts()
            except Exception:
                option_texts = []
            chosen_label = None
            for t in option_texts:
                if t and 'CSV' in t.upper():
                    chosen_label = t
                    break
            if chosen_label:
                try:
                    await cbs.nth(i).select_option(label=chosen_label)
                except Exception:
                    pass

                if await page.get_by_role('button', name='Export').count() > 0:
                    try:
                        async with page.expect_download() as dl:
                            await page.get_by_role('button', name='Export').first.click()
                        download = await dl.value
                        await download.save_as(filename)
                        return
                    except Exception:
                        try:
                            await page.get_by_role('button', name='Export').first.click()
                        except Exception:
                            pass
    except Exception:
        # Best-effort only; don't raise
        pass

    # If we get here, no download was captured. Leave the report visible for manual export.
    return

